import{_ as e,o as i,c as a,ag as o}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Provider Limits and Auto-Fallback","description":"","frontmatter":{},"headers":[],"relativePath":"reference/PROVIDER_LIMITS_AND_FALLBACK.md","filePath":"reference/PROVIDER_LIMITS_AND_FALLBACK.md","lastUpdated":1771123879000}'),r={name:"reference/PROVIDER_LIMITS_AND_FALLBACK.md"};function n(l,t,s,d,c,m){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="provider-limits-and-auto-fallback" tabindex="-1">Provider Limits and Auto-Fallback <a class="header-anchor" href="#provider-limits-and-auto-fallback" aria-label="Permalink to &quot;Provider Limits and Auto-Fallback&quot;">​</a></h1><h2 id="rate-limit-vs-usage-limit" tabindex="-1">Rate Limit vs Usage Limit <a class="header-anchor" href="#rate-limit-vs-usage-limit" aria-label="Permalink to &quot;Rate Limit vs Usage Limit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Meaning</th><th>Handling</th></tr></thead><tbody><tr><td><strong>Rate limit</strong></td><td>Too many requests per minute (429, &quot;rate limit&quot;, &quot;too many requests&quot;)</td><td>Retry same provider with exponential backoff (tenacity)</td></tr><tr><td><strong>Transient</strong></td><td>Gateway/network issues (502, 503, 504, &quot;reconnecting&quot;)</td><td>Retry same provider with exponential backoff</td></tr><tr><td><strong>Usage limit</strong></td><td>Subscription/quota exhausted (&quot;quota exceeded&quot;, &quot;usage limit&quot;, &quot;monthly limit&quot;)</td><td>Fallback to different provider (no retry same)</td></tr></tbody></table><h2 id="auto-fallback-chains" tabindex="-1">Auto-Fallback Chains <a class="header-anchor" href="#auto-fallback-chains" aria-label="Permalink to &quot;Auto-Fallback Chains&quot;">​</a></h2><p>When a provider hits a <strong>usage limit</strong>, thegent automatically tries the next provider in its fallback chain:</p><ul><li><strong>glm</strong> → minimax → antigravity → gemini</li><li><strong>minimax</strong> → glm → antigravity → gemini</li><li><strong>antigravity</strong> → minimax → glm → gemini</li><li><strong>gemini</strong> → codex → copilot → claude</li><li><strong>codex</strong> → gemini → copilot → claude</li><li><strong>copilot</strong> → gemini → codex → claude</li><li><strong>claude</strong> → gemini → codex → copilot</li><li><strong>cursor-agent</strong> → gemini → codex → claude</li></ul><p>Fallback only triggers on usage-limit errors. Other failures (config, unknown provider) do not trigger fallback.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><ul><li><code>src/thegent/agents/resilience.py</code>: <code>classify_failure()</code>, <code>is_retryable()</code>, <code>is_usage_limit()</code></li><li><code>src/thegent/agents/registry.py</code>: <code>get_fallback_agents()</code>, <code>_PROVIDER_FALLBACK_CHAIN</code></li><li>Retry: tenacity with exponential backoff (2–60s, 4 attempts)</li><li>Fallback: CLI and <code>run_impl</code> expand routes when usage limit detected</li></ul>',9)])])}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
